Here is the improved implementation of the NestJS API for searching files in a server data directory, addressing the concerns regarding error handling, input validation, and performance. The code is structured to fit into the specified files.

<FILEPATH>
src/app.controller.ts
</FILEPATH>
<CODE>
import { Controller, Post, Body, BadRequestException } from '@nestjs/common';
import { AppService } from './app.service';

@Controller('search')
export class AppController {
  constructor(private readonly appService: AppService) {}

  @Post()
  async searchFiles(@Body() body: { search_content?: string; search_filename?: string; search_dir?: string }) {
    // Validate search_dir format
    if (body.search_dir && !/^\/[a-zA-Z0-9/_-]*$/.test(body.search_dir)) {
      throw new BadRequestException('Invalid search_dir format');
    }
    // Validate search_content and search_filename for potential injection
    if (body.search_content && typeof body.search_content !== 'string') {
      throw new BadRequestException('search_content must be a string');
    }
    if (body.search_filename && typeof body.search_filename !== 'string') {
      throw new BadRequestException('search_filename must be a string');
    }
    return this.appService.searchFiles(body);
  }
}
</CODE>

<FILEPATH>
src/app.service.ts
</FILEPATH>
<CODE>
import { Injectable, BadRequestException } from '@nestjs/common';
import * as fs from 'fs/promises';
import * as path from 'path';

@Injectable()
export class AppService {
  private readonly dataDirectory = path.join(__dirname, '..', 'data');

  async searchFiles({ search_content, search_filename, search_dir }: { search_content?: string; search_filename?: string; search_dir?: string }) {
    const results: string[] = [];
    const searchPath = search_dir ? path.join(this.dataDirectory, search_dir) : this.dataDirectory;

    try {
      const files = await fs.readdir(searchPath);

      for (const file of files) {
        const filePath = path.join(searchPath, file);
        const stats = await fs.stat(filePath);

        if (stats.isFile()) {
          let contentMatches = true;
          let filenameMatches = true;

          if (search_content) {
            const fileContent = await fs.readFile(filePath, 'utf-8');
            contentMatches = fileContent.includes(search_content);
          }

          if (search_filename) {
            filenameMatches = file.startsWith(search_filename);
          }

          if (contentMatches || filenameMatches) {
            results.push(filePath);
          }
        }
      }
    } catch (error) {
      console.error('Error reading files:', error);
      throw new BadRequestException('Invalid input or directory does not exist');
    }

    return { files: results };
  }
}
</CODE>

